{$ param columns_md label="Desktop Columns" default="3" description="Number of columns at md+ breakpoint (2, 3, or 4)." $}
{$ param gap_class label="Gap Class" default="gap-6" description="Tailwind gap utility." $}

<div class="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-{$= columns_md $} {$= gap_class $} mb-8">
  {$ slot cards $}
    <!-- Drop Project Card, Event Card, Resource Card, etc. here -->
  {$ /slot $}
</div>
